    if len(unique_vals) < 2:
        raise ValueError("List must contain at least two distinct numbers")
    sorted_vals = sorted(unique_vals)
    return sorted_vals[1]

import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r' {2,}', ' ', s)

def is_decimal(value):
    try:
        s = str(value)
        if 'e' in s.lower():
            return False
        if '.' not in s:
            return False
        integer_part, decimal_part = s.split('.', 1)
        if len(decimal_part) == 2 and decimal_part.isdigit():
            # Check integer part can be empty or just a sign
            if integer_part in ('', '+', '-'):
                return False
            if integer_part[0] in ('+', '-'):
                integer_part = integer_part[1:]
            return integer_part.isdigit()
        return False
    except Exception:
        return False

def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return False

    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False

    # Check alternating pattern: s[0], s[1], s[0], s[1], ...
    first_char, second_char = s[0], s[1]
    if first_char == second_char:
        return False

    for i, ch in enumerate(s):
        expected_char = first_char if i % 2 == 0 else second_char
        if ch != expected_char:
            return False

    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0

    max_ending_here = max_so_far = arr[0]
    for num in arr[1:]:
        max_ending_here = max(num, max_ending_here + num)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def len_log(text: str) -> int:
    words = text.split()
    if not words:
        return 0
    return max(len(word) for word in words)

